# Sessione 22 - Durata fasi esterne = TT del ciclo (Tempo/set, lotto da 10 liner), in minuti.
# Fonte: ciclo T09 del 22/09 (prevale) + ciclo T08 v5 del 28/08. Esclusi P4000-10LA e P5000-10LA (a scorta).
# Postazione Lavorazione Esterna 24h senza Holiday List: il TT conta in giorni di calendario.
# SCRIVI = False -> solo prova. Uso: exec(open(f).read(), {"frappe": frappe, "SCRIVI": False})
SCRIVI = globals().get("SCRIVI", False)
bom_default = frappe.db.sql("SELECT name FROM `tabBOM` WHERE is_default=1 AND is_active=1 AND docstatus=1", pluck=True)
da_fare = []
uguali = 0
senza = []
for b in bom_default:
    for r in frappe.db.sql("SELECT name, time_in_mins, fixed_time, description FROM `tabBOM Operation` WHERE parent=%s AND workstation_type='Lavorazione Esterna'", b, as_dict=True):
        cod = frappe.utils.strip_html(r.description or "").strip().split(" ")[0]
        if cod not in TT_MIN:
            senza.append(cod)
            continue
        if abs((r.time_in_mins or 0) - TT_MIN[cod]) < 1 and r.fixed_time:
            uguali = uguali + 1
            continue
        da_fare.append([r.name, cod, r.time_in_mins, TT_MIN[cod]])
print("BOM default:", len(bom_default), "| da aggiornare:", len(da_fare), "| gia corrette:", uguali, "| non toccate:", len(senza), senza)
ore_prima = 0
ore_dopo = 0
for x in da_fare:
    ore_prima = ore_prima + (x[2] or 0) / 60
    ore_dopo = ore_dopo + x[3] / 60
print("Ore totali fasi aggiornate: prima %.0f h -> dopo %.0f h" % (ore_prima, ore_dopo))
for x in da_fare[:5]:
    print("   esempio:", x[1], x[2], "->", x[3])
if SCRIVI:
    import json
    with open("/home/frappe-user/backup_sessione22/bom_operation_esterne_prima_tt.json", "w") as fb:
        json.dump(da_fare, fb)
    print("Backup valori precedenti: /home/frappe-user/backup_sessione22/bom_operation_esterne_prima_tt.json")
    for x in da_fare:
        frappe.db.set_value("BOM Operation", x[0], {"time_in_mins": x[3], "fixed_time": 1}, update_modified=False)
    frappe.db.commit()
    ok = 0
    for x in da_fare:
        if abs(frappe.db.get_value("BOM Operation", x[0], "time_in_mins") - x[3]) < 1:
            ok = ok + 1
    print("-> scritto. Verificate:", ok, "su", len(da_fare))
else:
    print("PROVA: nessuna scrittura")
